import type { MetadataRoute } from "next";

/** Colors mirror --brand-900 and --ivory in globals.css. Icons are generated by scripts/generate-pwa-icons.mjs. */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "KSP GatePass",
    short_name: "GatePass",
    description: "Ticket sales and gate verification for KSP Hotel Gulu",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#faf7f0",
    theme_color: "#0a2a20",
    icons: [
      // "any": shown as-is (desktop install, app lists, splash).
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      // "maskable": full-bleed, mark kept inside the safe zone, so Android can crop it to any shape.
      { src: "/icons/icon-maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/icons/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
      // "monochrome": single-colour glyph for Android themed icons.
      { src: "/icons/icon-monochrome-512.png", sizes: "512x512", type: "image/png", purpose: "monochrome" },
    ],
  };
}
